<script setup lang="ts">
import { computed, reactive, ref, watch, nextTick, onBeforeUnmount } from 'vue';
import { request } from '../crm-api';
import type { ApiProduct } from '../api';
export interface QuoteDraft {id:string;inquiry_id:number;quote_id:number|null;revision:number;updated_at:string;data:QuoteData}
interface QuoteLine {product_id:number|'';width:number|string;height:number|string;unit:string;material:string;color:string;control:string;quantity:number|string;unit_price:number|string}
interface QuoteData {inquiry_id:number;locale:string;currency:string;valid_until:string;discount:number|string;shipping:number|string;tax:number|string;terms:string;lines:QuoteLine[]}
const props=defineProps<{record:QuoteDraft;products:ApiProduct[];company:string;locale:string}>();
const emit=defineEmits<{published:[version:{quote_id:number;version:number}];close:[];saved:[draft:QuoteDraft]}>();
const tx=(z:string,e:string)=>props.locale==='zh'?z:e;
const localKey=`vera-quote-draft-${props.record.id}`;
let initial=JSON.parse(JSON.stringify(props.record.data));
try{const cached=JSON.parse(sessionStorage.getItem(localKey)||'null');if(cached?.revision===props.record.revision)initial=cached.data}catch{}
const form=reactive<QuoteData>(initial),revision=ref(props.record.revision),dirty=ref(JSON.stringify(initial)!==JSON.stringify(props.record.data));
const error=ref(''),saving=ref(false),publishing=ref(false),checked=ref(false),savedAt=ref(props.record.updated_at);
let timer:ReturnType<typeof setTimeout>|undefined,inFlight:Promise<void>|null=null;
const blankLine=():QuoteLine=>({product_id:'',width:'',height:'',unit:'mm',material:'',color:'',control:'',quantity:1,unit_price:''});
const subtotal=computed(()=>form.lines.reduce((sum,l)=>sum+(Number(l.quantity)||0)*(Number(l.unit_price)||0),0));
const total=computed(()=>subtotal.value-(Number(form.discount)||0)+(Number(form.shipping)||0)+(Number(form.tax)||0));
const moneyOk=(v:number|string)=>v!==''&&Number.isFinite(Number(v))&&Number(v)>=0&&Math.abs(Number(v)*100-Math.round(Number(v)*100))<0.000001;
const issues=computed(()=>{const result:Record<string,string>={};
 if(!/^[A-Z]{3}$/.test(form.currency))result.currency=tx('请输入三位币种，例如NZD','Enter a three-letter currency, e.g. NZD');
 if(!form.valid_until||form.valid_until<new Date().toLocaleDateString('en-CA',{timeZone:'Pacific/Auckland'}))result.valid_until=tx('有效期不能早于今天','Validity must not be before today');
 form.lines.forEach((l,i)=>{const prefix=`lines.${i}.`;if(l.product_id===''||!props.products.some(p=>p.id===l.product_id))result[prefix+'product_id']=tx('请选择产品','Choose a product');for(const key of ['width','height'] as const)if(!Number.isFinite(Number(l[key]))||Number(l[key])<=0)result[prefix+key]=tx('请输入大于0的尺寸','Enter a positive dimension');for(const key of ['material','color','control'] as const)if(!l[key]?.trim())result[prefix+key]=tx('请确认此项','Confirm this field');if(!Number.isInteger(Number(l.quantity))||Number(l.quantity)<1)result[prefix+'quantity']=tx('数量须为正整数','Use a positive whole quantity');if(!moneyOk(l.unit_price))result[prefix+'unit_price']=tx('填写人工单价，最多两位小数','Enter a manual price with up to two decimals')});
 for(const key of ['discount','shipping','tax'] as const)if(!moneyOk(form[key]))result[key]=tx('金额须为非负数，最多两位小数','Use a non-negative amount with up to two decimals');
 if(Number(form.discount)>subtotal.value)result.discount=tx('折扣不能超过小计','Discount cannot exceed the subtotal');return result;
});
function fieldError(key:string){return checked.value?issues.value[key]:''}
function productOptions(line:QuoteLine,key:'colors'|'controls'){return props.products.find(p=>p.id===line.product_id)?.[key]||[]}
function selectProduct(index:number){const l=form.lines[index],p=props.products.find(p=>p.id===l.product_id);if(!p)return;l.material= form.locale==='zh'?p.material_zh:p.material_en;l.unit=p.unit||'mm';l.color=p.colors?.length===1?p.colors[0]:'';l.control=p.controls?.length===1?p.controls[0]:''}
function cache(){sessionStorage.setItem(localKey,JSON.stringify({revision:revision.value,data:form}))}
async function saveDraft():Promise<void>{
 clearTimeout(timer);if(inFlight){await inFlight;if(dirty.value)return saveDraft();return}if(!dirty.value)return;
 const snapshot=JSON.stringify(form);saving.value=true;error.value='';
 inFlight=(async()=>{try{const result=await request<QuoteDraft>(`quote-drafts/${props.record.id}`,{data:JSON.parse(snapshot),revision:revision.value});revision.value=result.revision;savedAt.value=result.updated_at;dirty.value=JSON.stringify(form)!==snapshot;cache();emit('saved',result)}catch(e){error.value=e instanceof Error?e.message:String(e);throw e}finally{saving.value=false;inFlight=null}})();await inFlight;
}
watch(form,()=>{dirty.value=true;cache();clearTimeout(timer);timer=setTimeout(()=>{void saveDraft().catch(()=>{})},1500)},{deep:true});
if(dirty.value)timer=setTimeout(()=>{void saveDraft().catch(()=>{})},1500);
onBeforeUnmount(()=>{clearTimeout(timer);if(dirty.value)cache()});
async function publish(){checked.value=true;if(Object.keys(issues.value).length){await nextTick();document.querySelector<HTMLElement>('.quotation-editor [aria-invalid=true]')?.focus();return}publishing.value=true;try{await saveDraft();const result=await request<{quote_id:number;version:number}>(`quote-drafts/${props.record.id}/publish`,{revision:revision.value});sessionStorage.removeItem(localKey);emit('published',result)}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{publishing.value=false}}
async function close(){try{await saveDraft();emit('close')}catch{}}
</script>
<template>
 <form class="quotation-editor" novalidate @submit.prevent="publish">
  <header class="document-heading"><div><span class="eyebrow">{{record.quote_id?`Q-${record.quote_id} / ${tx('修订草稿','REVISION')}`:tx('报价草稿','QUOTATION DRAFT')}}</span><h2>{{company}}</h2><p>{{tx('先整理方案，核对完成后生成正式报价。','Prepare the proposal, then finalize a version after review.')}}</p></div><button type="button" class="quiet-button" :disabled="publishing" @click="close">{{tx('返回列表','Back to list')}} ↗</button></header>
  <div class="document-layout"><div class="document-main">
   <section class="document-section"><h3><span>01</span>{{tx('报价条件','Quote terms')}}</h3><div class="fields three"><label>{{tx('报价语言','Document language')}}<select v-model="form.locale" :disabled="publishing"><option value="zh">中文</option><option value="en">English</option></select></label><label>{{tx('币种','Currency')}}<input v-model="form.currency" maxlength="3" :aria-invalid="!!fieldError('currency')" :disabled="publishing" /><small class="field-error">{{fieldError('currency')}}</small></label><label>{{tx('有效期','Valid until')}}<input v-model="form.valid_until" type="date" :aria-invalid="!!fieldError('valid_until')" :disabled="publishing"/><small class="field-error">{{fieldError('valid_until')}}</small></label></div></section>
   <section class="document-section"><div class="section-title"><h3><span>02</span>{{tx('产品明细','Product specification')}}</h3><button type="button" class="quiet-button" :disabled="publishing" @click="form.lines.push(blankLine())">+ {{tx('添加产品','Add item')}}</button></div>
    <article v-for="(line,index) in form.lines" :key="index" class="quote-line"><div class="line-heading"><strong>{{tx('产品','ITEM')}} {{String(index+1).padStart(2,'0')}}</strong><button v-if="form.lines.length>1" type="button" class="remove-button" :disabled="publishing" @click="form.lines.splice(index,1)">{{tx('移除','Remove')}}</button></div>
     <div class="fields three"><label class="product-select">{{tx('选择产品','Product')}}<select v-model="line.product_id" :aria-invalid="!!fieldError(`lines.${index}.product_id`)" :disabled="publishing" @change="selectProduct(index)"><option value="">{{tx('选择目录产品','Choose from catalogue')}}</option><option v-for="p in products" :key="p.id" :value="p.id">{{form.locale==='zh'?p.name_zh:p.name_en}}</option></select><small class="field-error">{{fieldError(`lines.${index}.product_id`)}}</small></label><label>{{tx('宽度','Width')}}<input v-model="line.width" type="number" step="any" :disabled="publishing" :aria-invalid="!!fieldError(`lines.${index}.width`)"/><small class="field-error">{{fieldError(`lines.${index}.width`)}}</small></label><label>{{tx('高度','Drop')}}<input v-model="line.height" type="number" step="any" :disabled="publishing" :aria-invalid="!!fieldError(`lines.${index}.height`)"/><small class="field-error">{{fieldError(`lines.${index}.height`)}}</small></label><label>{{tx('单位','Unit')}}<select v-model="line.unit" :disabled="publishing"><option>mm</option><option>inch</option></select></label><label>{{tx('材质','Material')}}<input v-model="line.material" :disabled="publishing" :aria-invalid="!!fieldError(`lines.${index}.material`)"/><small class="field-error">{{fieldError(`lines.${index}.material`)}}</small></label><label>{{tx('颜色','Colour')}}<input v-model="line.color" :list="`quote-colours-${index}`" :disabled="publishing" :aria-invalid="!!fieldError(`lines.${index}.color`)"/><datalist :id="`quote-colours-${index}`"><option v-for="v in productOptions(line,'colors')" :key="v" :value="v"/></datalist><small class="field-error">{{fieldError(`lines.${index}.color`)}}</small></label><label>{{tx('控制方式','Control')}}<input v-model="line.control" :list="`quote-controls-${index}`" :disabled="publishing" :aria-invalid="!!fieldError(`lines.${index}.control`)"/><datalist :id="`quote-controls-${index}`"><option v-for="v in productOptions(line,'controls')" :key="v" :value="v"/></datalist><small class="field-error">{{fieldError(`lines.${index}.control`)}}</small></label><label>{{tx('数量','Quantity')}}<input v-model="line.quantity" type="number" step="any" :disabled="publishing" :aria-invalid="!!fieldError(`lines.${index}.quantity`)"/><small class="field-error">{{fieldError(`lines.${index}.quantity`)}}</small></label><label>{{tx('人工单价','Manual unit price')}}<input v-model="line.unit_price" type="number" step="any" :disabled="publishing" :aria-invalid="!!fieldError(`lines.${index}.unit_price`)"/><small class="field-error">{{fieldError(`lines.${index}.unit_price`)}}</small></label></div>
    </article>
   </section><section class="document-section"><h3><span>03</span>{{tx('费用与条款','Charges & terms')}}</h3><div class="fields three"><label v-for="field in [{key:'discount',label:tx('折扣','Discount')},{key:'shipping',label:tx('运费','Shipping')},{key:'tax',label:tx('税额','Tax amount')}]" :key="field.key">{{field.label}}<input v-model="form[field.key as 'discount'|'shipping'|'tax']" type="number" step="any" :disabled="publishing" :aria-invalid="!!fieldError(field.key)"/><small class="field-error">{{fieldError(field.key)}}</small></label></div><label>{{tx('商务条款','Commercial terms')}}<textarea v-model="form.terms" maxlength="4000" :disabled="publishing" :placeholder="tx('填写已确认的付款、交付与其他约定。','Enter the agreed payment, delivery and other terms.')"/></label></section>
  </div><aside class="document-summary"><span class="eyebrow">{{tx('报价摘要','PROPOSAL SUMMARY')}}</span><h3>{{form.currency}} {{total.toFixed(2)}}</h3><dl><div><dt>{{tx('产品项','Items')}}</dt><dd>{{form.lines.length}}</dd></div><div><dt>{{tx('小计','Subtotal')}}</dt><dd>{{subtotal.toFixed(2)}}</dd></div><div><dt>{{tx('折扣','Discount')}}</dt><dd>− {{Number(form.discount||0).toFixed(2)}}</dd></div><div><dt>{{tx('运费 / 税额','Shipping / tax')}}</dt><dd>{{Number(form.shipping||0).toFixed(2)}} / {{Number(form.tax||0).toFixed(2)}}</dd></div></dl><p>{{tx('草稿可保留缺项，正式报价须核对完整规格和人工价格。','Drafts can contain missing details. Review specifications and manual prices before finalizing.')}}</p><span class="save-state" role="status">{{saving?tx('正在保存…','Saving…'):dirty?tx('更改待保存','Changes pending'):tx('草稿已保存','Draft saved')}}</span></aside></div>
  <p v-if="checked&&Object.keys(issues).length" role="alert" class="editor-error">{{tx('请检查标红的字段；你仍可保存草稿。','Review the highlighted fields. You can still save this draft.')}}</p><p v-if="error" role="alert" class="editor-error">{{error}}</p><footer class="document-actions"><span>{{tx('正式版本会保留规格与金额快照。','Final versions retain the specification and price snapshot.')}}</span><button type="button" class="secondary-button" :disabled="saving||publishing" @click="saveDraft().catch(()=>{})">{{tx('保存草稿','Save draft')}}</button><button class="primary-button" :disabled="publishing||saving">{{publishing?tx('正在生成…','Finalizing…'):tx('生成正式报价','Finalize quotation')}} →</button></footer>
 </form>
</template>
<style scoped>
.quotation-editor{font-family:var(--font-body);color:#1c2922}.document-heading{display:flex;justify-content:space-between;align-items:flex-start;gap:24px;padding:4px 0 28px;border-bottom:1px solid #e0e7e2}.eyebrow{font-size:10px;letter-spacing:.13em;font-weight:600;color:#718076}.document-heading h2{font-size:27px;line-height:1.25;font-weight:600;margin:10px 0}.document-heading p{font-size:13px;color:#718076;margin:0}.quotation-editor button{font:500 12px var(--font-body);cursor:pointer}.quiet-button{padding:8px 0;border:0;background:transparent;color:#53675b;min-height:36px}.document-layout{display:grid;grid-template-columns:minmax(0,1fr) 230px;gap:36px;align-items:start}.document-main{min-width:0}.document-section{padding:26px 0;border-bottom:1px solid #e4eae6}.document-section h3{display:flex;align-items:center;gap:12px;font-size:15px;font-weight:600;margin:0 0 20px}.document-section h3 span{font-size:10px;color:#91a096;font-variant-numeric:tabular-nums}.section-title{display:flex;justify-content:space-between;gap:16px;align-items:center;margin-bottom:18px}.section-title h3{margin:0}.fields{display:grid;gap:12px 16px}.fields.three{grid-template-columns:repeat(3,minmax(0,1fr))}.quotation-editor label{display:block;font-size:12px;color:#526257;min-width:0}.quotation-editor input,.quotation-editor select,.quotation-editor textarea{display:block;width:100%;box-sizing:border-box;margin:7px 0 0;border:1px solid #d7e0d9;border-radius:5px;padding:11px 12px;background:#fff;color:#1c2922;font:13px var(--font-body);min-height:42px}.quotation-editor textarea{min-height:110px;margin-top:10px;resize:vertical}.quotation-editor input:focus,.quotation-editor select:focus,.quotation-editor textarea:focus{outline:2px solid #d9e9df;border-color:#0f6e5c}.quotation-editor [aria-invalid=true]{border-color:#ba5541;background:#fffaf8}.field-error{display:block;min-height:0;color:#a34232;font-size:11px;line-height:1.5;margin-top:5px}.field-error:empty{display:none}.quote-line{padding:18px 0;margin:0;border-top:1px solid #edf0ec}.quote-line:first-of-type{border-top:0;padding-top:0}.line-heading{display:flex;justify-content:space-between;align-items:center;margin-bottom:16px}.line-heading strong{font-size:11px;font-weight:600;letter-spacing:.06em;color:#748478}.remove-button{padding:0;border:0;color:#a34232;background:transparent;font-size:11px;min-height:30px}.document-summary{position:sticky;top:24px;margin-top:28px;padding:22px;background:#f3f6f2;border-radius:6px}.document-summary h3{font-size:25px;line-height:1.2;margin:14px 0 24px;letter-spacing:-.02em;font-variant-numeric:tabular-nums}.document-summary dl{margin:0}.document-summary dl div{display:flex;justify-content:space-between;gap:10px;font-size:12px;line-height:1.6;margin:12px 0}.document-summary dt{color:#748478}.document-summary dd{margin:0;text-align:right}.document-summary p{font-size:11px;line-height:1.8;color:#748478;border-top:1px solid #dfe7df;padding-top:16px;margin:20px 0 14px}.save-state{font-size:11px;color:#0f6e5c}.document-actions{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-top:20px;padding:20px 0 0}.document-actions>span{font-size:11px;color:#839086;margin-right:auto;max-width:250px}.primary-button,.secondary-button{padding:11px 16px;min-height:42px;border-radius:5px;border:1px solid #0f6e5c;background:#0f6e5c;color:#fff}.secondary-button{background:#fff;color:#526257;border-color:#d7e0d9}.quotation-editor button:disabled{opacity:.55;cursor:default}.editor-error{padding:12px 14px;color:#a34232;background:#fff5f0;font-size:12px;line-height:1.6}@media(max-width:1450px){.document-layout{grid-template-columns:1fr}.document-summary{position:static;margin-top:0}.document-summary dl{display:grid;grid-template-columns:1fr 1fr;gap:0 24px}.document-summary h3{margin-bottom:12px}.document-summary p{margin-top:12px}}@media(max-width:640px){.document-heading{gap:12px;padding-bottom:22px}.document-heading h2{font-size:22px}.document-heading p{font-size:12px}.fields.three{grid-template-columns:repeat(2,minmax(0,1fr))}.product-select{grid-column:1/-1}.document-actions>span{flex-basis:100%;max-width:none}.document-actions button{flex:1;padding:10px 12px;font-size:11px}.document-summary{padding:18px}.document-summary h3{font-size:23px}}
</style>
